IF OBJECT_ID('dbo.Trim') IS  NULL
EXECUTE(
	'CREATE FUNCTION dbo.TRIM(@string NVARCHAR(MAX))
	RETURNS NVARCHAR(MAX)
	BEGIN
	RETURN LTRIM(RTRIM(@string))
	END')
GO

delete from DepartmentPriorities where (select count(*) from requests where priorityid = DepartmentPriorities.PriorityId) = 0
delete from Priorities where (select count(*) from requests where priorityid = Priorities.Id) = 0
go

update Priorities set NameArabic = dbo.trim(namearabic)
go




IF  NOT EXISTS (SELECT * FROM dbo.Departments  WHERE id = (select d.id from departments d, colleges c where d.collegeid = c.id and d.NameArabic = N'الجغرافيا' and c.NameArabic = N'الشريعة بالأحساء')) 
BEGIN 	insert into dbo.Departments (NameArabic, NameEnglish, CollegeId, Created, Updated, CreatedBy, UpdatedBy, Field) 
values  		( 			
				N'الجغرافيا',
				N'Geography',

				(select id from colleges where NameArabic = N'الشريعة بالأحساء') ,
				getdate(),
				getdate(),
				'00000000-0000-0000-0000-000000000000',
				'00000000-0000-0000-0000-000000000000',
				3
);  END


